/**
 * Typed access to the merged game data in `src/data/game/*.json`
 * (generated by `npm run build:data`; never edit those files by hand).
 *
 * JSON imports are inferred with plain `string` types, so they are cast to the
 * contract in `src/engine/data-types.ts` here, once, for everybody.
 */
import type {
  Ability,
  GameData,
  Item,
  Move,
  Nature,
  Species,
  TypesFile,
} from '../engine/data-types'
import abilitiesJson from './game/abilities.json'
import itemsJson from './game/items.json'
import movesJson from './game/moves.json'
import naturesJson from './game/natures.json'
import speciesJson from './game/species.json'
import typesJson from './game/types.json'

export const species = speciesJson as unknown as Species[]
export const moves = movesJson as unknown as Move[]
export const abilities = abilitiesJson as unknown as Ability[]
export const types = typesJson as unknown as TypesFile
export const natures = naturesJson as unknown as Nature[]
export const items = itemsJson as unknown as Item[]

export const gameData: GameData = { species, moves, abilities, types, natures, items }
